import{_ as a,a as t,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"日志采集与查询：基础对象与机制","description":"按 事件身份、多行合并、偏移重读与脱敏 的实际关系组织。","frontmatter":{"title":"日志采集与查询：基础对象与机制","description":"按 事件身份、多行合并、偏移重读与脱敏 的实际关系组织。","showdocs":{"topics":[{"id":"observability","title":"日志采集与查询","link":"/topics/observability/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"日志采集与查询机制与任务课程","summary":"按 事件身份、多行合并、偏移重读与脱敏 的实际关系组织。","status":"active","related":[{"title":"日志采集与查询：配置日志采集与批处理","link":"/systems/logging-monitoring/observability/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"ELK 组件与日志查询笔记","link":"/systems/logging-monitoring/observability/plus/subjects/elk-%E6%97%A5%E5%BF%97%E9%87%87%E9%9B%86","kind":"知识专题","scope":"general","audience":"general"},{"title":"日志采集与查询：发布、排障与恢复练习","link":"/systems/logging-monitoring/observability/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"SLS 查询与日志分析","link":"/systems/logging-monitoring/observability/plus/ecosystem/sls-query","kind":"命令与查询","scope":"general","audience":"general"}],"prev":false,"next":{"text":"日志采集与查询：配置日志采集与批处理","link":"/systems/logging-monitoring/observability/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"日志采集与查询：配置日志采集与批处理","link":"/systems/logging-monitoring/observability/plus/practice/application"}},"headers":[],"relativePath":"systems/logging-monitoring/observability/log-pipeline.md","filePath":"systems/logging-monitoring/observability/log-pipeline.md"}'),l={name:"systems/logging-monitoring/observability/log-pipeline.md"};function s(o,e,n,p,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="日志采集与查询-基础对象与机制" tabindex="-1">日志采集与查询：基础对象与机制 <a class="header-anchor" href="#日志采集与查询-基础对象与机制" aria-label="Permalink to &quot;日志采集与查询：基础对象与机制&quot;">​</a></h1><h2 id="part-1" tabindex="-1">日志事件、采集器与查询入门 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;日志事件、采集器与查询入门 {#part-1}&quot;">​</a></h2><p>日志管理需要串起事件产生、文件读取、传输、索引和查询。先统一时间、服务与关联标识，再处理多行和偏移；查询没有结果时应逐段找证据，不应直接认定应用没有写日志。</p><h3 id="part-1-roles" tabindex="-1">事件职责 <a class="header-anchor" href="#part-1-roles" aria-label="Permalink to &quot;事件职责 {#part-1-roles}&quot;">​</a></h3><p>日志事件职责是保存某次离散事实：事件时间、服务、级别、请求关联和必要上下文。指标适合汇总趋势，告警适合通知需要处理的条件，不能让每条ERROR直接等于一次事故。应用写文件、采集器读文件、存储建立索引、查询端筛选，这是四个独立失败边界；ELK中Elasticsearch索引搜索、Logstash转换、Kibana展示，产品名不等于端到端成功。raw.log的三次请求用于区分一条事件和一行物理文本。</p><h3 id="part-1-query" tabindex="-1">检索表达式 <a class="header-anchor" href="#part-1-query" aria-label="Permalink to &quot;检索表达式 {#part-1-query}&quot;">​</a></h3><p>日志检索表达式必须先确认时间范围、区域、Project和Logstore，再写关键词或字段条件。SLS的查询与分析以竖线分隔，字段过滤先缩小输入，SQL再统计；字段有值不代表已启用相应索引和统计能力。示例条件service:checkout and level:ERROR仅在实际结构化字段与索引匹配时有效；不能把Python输出里的message子串当作独立service字段。只按error全文搜索会漏掉未分词、大小写或编码不同的事件。</p><h3 id="part-1-scope" tabindex="-1">权限和时间边界 <a class="header-anchor" href="#part-1-scope" aria-label="Permalink to &quot;权限和时间边界 {#part-1-scope}&quot;">​</a></h3><p>日志时间边界需要区分应用事件时间、采集时间与入库时间，统一UTC并保留偏移含义。机器时钟偏差、队列延迟和时间选择器都可能让正确查询看不到事件。原日志目录应由应用写、采集身份读，状态目录由采集身份独占；读取所有主机文件的root权限不是入门必要条件。Windows读取路径要替换，不能直接使用示例Linux /srv路径；macOS不纳入运行验收。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：关键词命中了message中的service=checkout，能否保证service:checkout字段查询可用？</p><details><summary>参考解答</summary><p>不能。message中的字符串不等于独立字段；必须核对解析结果、service字段及索引规则，SLS分析还要核对统计能力。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><a href="https://www.elastic.co/guide/en/beats/filebeat/8.19/multiline-examples.html" target="_blank" rel="noopener noreferrer">Filebeat事件合并</a></li><li><a href="https://www.elastic.co/guide/en/beats/filebeat/8.19/filebeat-input-filestream.html" target="_blank" rel="noopener noreferrer">Filebeat filestream</a></li><li><a href="https://www.alibabacloud.com/help/zh/sls/" target="_blank" rel="noopener noreferrer">SLS中文入口</a></li></ul><p>继续阅读<a href="#part-2-multiline">机制</a>、<a href="/systems/logging-monitoring/observability/plus/practice/application#files">完整实践</a>、<a href="/systems/logging-monitoring/observability/operations#part-1-rotation">运维</a>、<a href="/systems/logging-monitoring/observability/operations#part-2-empty">诊断</a>与<a href="/systems/logging-monitoring/observability/operations#part-3-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">多行合并、偏移与数据保护 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;多行合并、偏移与数据保护 {#part-2}&quot;">​</a></h2><p>先明确源文件身份、编码、采集偏移和索引时间窗，再对照<a href="/systems/logging-monitoring/observability/plus/practice/application#source">配套示例</a>理解事件边界、输出确认与查询命中。</p><p>核对日期2026-10-17；适用范围：Filebeat 8.19 filestream教学配置；SLS按2026-10-17在线中文文档的查询/索引概念核对，不固定云端后端版本。8.19归档文档不是当前安装建议。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="#part-1-roles">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-2-multiline" tabindex="-1">多行事件合并 <a class="header-anchor" href="#part-2-multiline" aria-label="Permalink to &quot;多行事件合并 {#part-2-multiline}&quot;">​</a></h3><p>日志多行合并以新事件起始模式识别边界：ISO时间戳开头为新事件，其后堆栈归入上一事件。Filebeat配置在filestream输入侧合并，防止来自不同主机的行在下游串接。最大行数和超时是资源及延迟上限，超长/迟到堆栈可能被截断或拆分，不能保证无限堆栈完整。示例Python文件结束时自然完成最后一条，Filebeat则有持续采集的超时语义，两者不是同一实现。</p><h3 id="part-2-offset" tabindex="-1">字节偏移与重读 <a class="header-anchor" href="#part-2-offset" aria-label="Permalink to &quot;字节偏移与重读 {#part-2-offset}&quot;">​</a></h3><p>日志断点偏移记录文件身份及已处理位置，字节偏移不是行号；UTF-8汉字可能占多个字节。重命名轮转与copytruncate的身份变化不同，registry丢失、输入ID变化或错误清理会触发重读或漏读。下游确认之前已读取并不等于已持久入库；重试可能重复，因此用稳定event_id或请求序号辅助核对，不能声称仅靠偏移实现端到端恰好一次。normalize.py仅输出每事件开始偏移，每次从头读，没有断点恢复。</p><h3 id="part-2-redaction" tabindex="-1">脱敏与白名单 <a class="header-anchor" href="#part-2-redaction" aria-label="Permalink to &quot;脱敏与白名单 {#part-2-redaction}&quot;">​</a></h3><p>日志脱敏白名单应在写入原始日志之前决定可记录字段，禁止Authorization、Cookie、密码与身份证原文。例子的邮箱替换和token正则仅覆盖教学格式，Unicode、JSON转义、嵌套字段和其他秘密不能靠这两条正则完整识别。Filebeat配置更保守地移除整个自由文本message并填固定标记，因此输出丢失错误细节但避免假称有通用脱敏能力。文件路径、主机标签也可能敏感，保留元数据前仍需审核。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：删registry后是否只是从最后成功位置续读？</p><details><summary>参考解答</summary><p>不保证。断点状态丢失可能从头重读，文件身份与路径策略还可能造成漏读，应先备份并核对输出确认与事件ID。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p>',29)])])}const m=a(l,[["render",s]]);export{d as __pageData,m as default};
